"use client";
/**
 * US map of the 7 ISO grids. Footprints are APPROXIMATED BY WHOLE STATES
 * (real ISO boundaries cross state lines). Identity is carried by direct labels,
 * not by color: the selected grid is the only colored one. Click/Enter selects.
 * Geometry: lib/us-map.json, generated by scripts/build-us-map.mjs from us-atlas.
 */
import { useState } from "react";
import map from "@/lib/us-map.json";
import type { RegionInfo } from "@/lib/types";

type IsoShape = { d: string; cx: number; cy: number };
const ISOS = map.isos as Record<string, IsoShape>;

// Label nudges (viewBox units) where a centroid label would crowd neighbors.
const NUDGE: Record<string, [number, number]> = { CAISO: [-6, 0], ISONE: [10, 4], NYISO: [-8, 6], PJM: [6, 12] };

function split(label: string): [string, string] {
  const m = label.match(/^(\S+)\s*\(([^)]+)\)/);
  return m ? [m[1], m[2]] : [label, ""];
}

export default function GridMap({ regions, selected, onSelect, presenter }: {
  regions: RegionInfo[];
  selected: string;
  onSelect: (id: string) => void;
  presenter: boolean;
}) {
  const [hover, setHover] = useState<string | null>(null);
  const byId = Object.fromEntries(regions.map((r) => [r.id, r]));
  const [vx, vy, vw, vh] = map.viewBox;

  return (
    <section className="card p-4 flex flex-col gap-2" aria-label="Grid regions map">
      <svg viewBox={`${vx} ${vy} ${vw} ${vh}`} className="w-full" style={{ maxHeight: presenter ? "70vh" : "62vh" }} role="group"
        aria-label="Map of US grid operators. Select one to load its data.">
        <g>
          {map.states.map((s) => (
            <path key={s.id} d={s.d} fill={s.iso ? "var(--iso-fill)" : "var(--surface-2)"} stroke="var(--surface-1)" strokeWidth={0.8}>
              <title>{s.name}{s.iso ? ` · ${split(byId[s.iso]?.label ?? s.iso)[0]}` : " · no ISO in this app"}</title>
            </path>
          ))}
        </g>
        {Object.entries(ISOS).map(([id, iso]) => {
          const sel = id === selected;
          const hot = id === hover;
          return (
            <g key={id} role="button" tabIndex={0} aria-pressed={sel} aria-label={byId[id]?.label ?? id} style={{ cursor: "pointer", outline: "none" }}
              onClick={() => onSelect(id)} onKeyDown={(e) => (e.key === "Enter" || e.key === " ") && (e.preventDefault(), onSelect(id))}
              onMouseEnter={() => setHover(id)} onMouseLeave={() => setHover(null)} onFocus={() => setHover(id)} onBlur={() => setHover(null)}>
              <path d={iso.d} fill={sel ? "var(--accent)" : hot ? "var(--iso-hover)" : "transparent"}
                stroke={sel ? "var(--accent)" : "var(--iso-edge)"} strokeWidth={sel || hot ? 2.2 : 1.2} />
            </g>
          );
        })}
        {Object.entries(ISOS).map(([id, iso]) => {
          const [name, area] = split(byId[id]?.label ?? id);
          const [dx, dy] = NUDGE[id] ?? [0, 0];
          const sel = id === selected;
          const fill = sel ? "#ffffff" : "var(--text-primary)";
          const small = id === "NYISO" || id === "ISONE";
          return (
            <g key={`l-${id}`} pointerEvents="none" textAnchor="middle">
              <text x={iso.cx + dx} y={iso.cy + dy} fontSize={small ? 13 : 19} fontWeight={700} fill={fill}
                stroke={sel ? "none" : "var(--surface-1)"} strokeWidth={3} paintOrder="stroke">{name}</text>
              {!small && area && (
                <text x={iso.cx + dx} y={iso.cy + dy + 18} fontSize={13} fill={sel ? "#ffffff" : "var(--text-secondary)"}
                  stroke={sel ? "none" : "var(--surface-1)"} strokeWidth={3} paintOrder="stroke">{area.replace(/ – California/, "")}</text>
              )}
            </g>
          );
        })}
      </svg>
      {!presenter && (
        <div className="flex flex-wrap items-center gap-x-5 gap-y-1 text-sm secondary">
          <span className="flex items-center gap-1.5"><span style={{ background: "var(--accent)", width: 12, height: 12, borderRadius: 2 }} />Selected grid</span>
          <span className="flex items-center gap-1.5"><span style={{ background: "var(--iso-fill)", width: 12, height: 12, borderRadius: 2 }} />Other ISO in this app</span>
          <span className="flex items-center gap-1.5"><span style={{ background: "var(--surface-2)", border: "1px solid var(--border)", width: 12, height: 12, borderRadius: 2 }} />No ISO (utility-run)</span>
          <span className="muted ml-auto">Click a grid to load it. Footprints approximated by whole states; real ISO borders cross state lines.</span>
        </div>
      )}
    </section>
  );
}
